const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([73.931617, 31.998723]);
  const region = point.buffer(10000); // 10km radius

  const earlyStart = '2003-01-01';
  const earlyEnd = '2005-12-31';
  const lateStart = '2011-01-01';
  const lateEnd = '2013-12-31';

  // 2. Data Acquisition & Check
  const earlyCol = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/MASCON_CRI')
    .filterDate(earlyStart, earlyEnd)
    .filterBounds(region)
    .select('lwe_thickness');

  const lateCol = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/MASCON_CRI')
    .filterDate(lateStart, lateEnd)
    .filterBounds(region)
    .select('lwe_thickness');

  const earlySize = await earlyCol.size().getInfo();
  const lateSize = await lateCol.size().getInfo();

  console.log(`Early period (2003-2005) images: ${earlySize}`);
  console.log(`Late period (2011-2013) images: ${lateSize}`);

  if (earlySize === 0 || lateSize === 0) {
    console.log("No data available for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean water thickness for each period
  const earlyMean = earlyCol.mean();
  const lateMean = lateCol.mean();

  // 4. Calculation
  const earlyValue = await earlyMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const lateValue = await lateMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const earlyCount = await earlyMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  console.log(`Early period mean LWE: ${earlyValue !== null ? earlyValue.toFixed(2) : 'null'} mm`);
  console.log(`Late period mean LWE: ${lateValue !== null ? lateValue.toFixed(2) : 'null'} mm`);
  console.log(`Valid pixels: ${earlyCount}`);

  // 5. Validation & Final Answer
  if (earlyCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (earlyValue === null || lateValue === null || isNaN(earlyValue) || isNaN(lateValue)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  const change = lateValue - earlyValue;
  console.log(`Change in groundwater storage: ${change.toFixed(2)} mm`);
  console.log(`Decline detected: ${change < -20 ? 'Yes' : 'No'}`);

  // Significant decline is defined as >20mm decrease
  if (change < -20) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
